import type { SynapseEnhancedHttpClient } from "../utils/http.ts";
import { validateUserId, validateArray } from "../utils/validator.ts";

export class BlockedUsersApi {
    public constructor(private httpClient: SynapseEnhancedHttpClient) {}

    public async getBlocked(): Promise<{
        blocked_users: string[];
        total: number;
    }> {
        const response = await this.httpClient.get<{
            blocked_users: string[];
            total: number;
        }>("/_matrix/client/v1/friends/blocked");
        return response.data;
    }

    public async addUserToBlocked(userId: string): Promise<{
        user_id: string;
        status: string;
        total_blocked: number;
    }> {
        validateUserId(userId);

        const response = await this.httpClient.post<{
            user_id: string;
            status: string;
            total_blocked: number;
        }>("/_matrix/client/v1/friends/blocked", { user_id: userId });
        return response.data;
    }

    public async checkBlocked(userId: string): Promise<{
        user_id: string;
        is_blocked: boolean;
    }> {
        validateUserId(userId);

        const response = await this.httpClient.get<{
            user_id: string;
            is_blocked: boolean;
        }>(`/_matrix/client/v1/friends/blocked/${encodeURIComponent(userId)}`);
        return response.data;
    }

    public async removeBlocked(userId: string): Promise<{
        user_id: string;
        status: string;
        total_blocked: number;
    }> {
        validateUserId(userId);

        const response = await this.httpClient.delete<{
            user_id: string;
            status: string;
            total_blocked: number;
        }>(`/_matrix/client/v1/friends/blocked/${encodeURIComponent(userId)}`);
        return response.data;
    }

    public async batchBlockUsers(userIds: string[]): Promise<{
        results: Array<{
            user_id: string;
            is_blocked: boolean;
            status: string;
        }>;
        total_updated: number;
    }> {
        validateArray(userIds, "userIds", {
            minLength: 1,
            maxLength: 100,
            itemValidator: (item: unknown) => validateUserId(item as string),
        });

        const response = await this.httpClient.post<{
            results: Array<{
                user_id: string;
                is_blocked: boolean;
                status: string;
            }>;
            total_updated: number;
        }>("/_matrix/client/v1/friends/blocked/batch", { user_ids: userIds });
        return response.data;
    }
}
